 private void shareQueryOptions(){if(stopInput==null||stopInput.getText().toString().trim().length()==0){Toast.makeText(this,"Önce durak numarası gir.",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Sorguyu paylaş").setItems(new String[]{"Metin olarak paylaş","Görsel olarak paylaş","Görseli PNG kaydet"},new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int which){String stop=stopInput.getText().toString().trim(),line=lineInput.getText().toString().trim();try{if(which==0){Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/plain");send.putExtra(Intent.EXTRA_TEXT,"Transit TR · "+CityRegistry.get(city).name+" · Durak "+stop+(line.length()>0?" · Hat "+line:""));startActivity(Intent.createChooser(send,"Sorguyu paylaş"));return;}android.net.Uri uri=ShareCard.create(TransitActivity.this,CityRegistry.get(city).name,stop,line,snapshot);if(which==1){Intent send=new Intent(Intent.ACTION_SEND);send.setType("image/png");send.putExtra(Intent.EXTRA_STREAM,uri);send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);Intent chooser=Intent.createChooser(send,"Görseli paylaş");chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(chooser);}else if(Build.VERSION.SDK_INT>=19){Intent save=new Intent("android.intent.action.CREATE_DOCUMENT");save.addCategory(Intent.CATEGORY_OPENABLE);save.setType("image/png");save.putExtra("android.intent.extra.TITLE","Transit-TR-"+stop+".png");startActivityForResult(save,8041);}else{java.io.File folder=new java.io.File(android.os.Environment.getExternalStorageDirectory(),"Download");if(!folder.exists()&&!folder.mkdirs())throw new java.io.IOException("İndirme klasörü oluşturulamadı");String base="Transit-TR-"+stop+"-"+System.currentTimeMillis();java.io.File dest=new java.io.File(folder,base+".png");copyShareImage(new java.io.FileOutputStream(dest));android.media.MediaScannerConnection.scanFile(TransitActivity.this,new String[]{dest.getAbsolutePath()},new String[]{"image/png"},null);Toast.makeText(TransitActivity.this,"PNG İndirilenler'e kaydedildi",Toast.LENGTH_LONG).show();}}catch(Exception e){Toast.makeText(TransitActivity.this,"İşlem tamamlanamadı: "+e.getMessage(),Toast.LENGTH_LONG).show();}}}).show();}
 private void copyShareImage(java.io.OutputStream output)throws java.io.IOException{java.io.InputStream in=new java.io.FileInputStream(new java.io.File(new java.io.File(getCacheDir(),"share"),"query.png"));try{byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)output.write(b,0,n);output.flush();}finally{try{in.close();}finally{output.close();}}}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==8041&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null)try{java.io.OutputStream out=getContentResolver().openOutputStream(data.getData());if(out==null)throw new java.io.IOException("Dosya açılamadı");copyShareImage(out);Toast.makeText(this,"PNG kaydedildi",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"PNG kaydedilemedi: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
